import { SupportedCity } from "../../../lib/trip-domain";

export type AttractionCategoryType = "명소" | "자연" | "엔터" | "쇼핑";

export type PriceStatus = "FREE" | "PAID" | "PARTIALLY_PAID" | "UNCONFIRMED";

export interface AttractionSpot {
  id: string;
  cityCode: SupportedCity;
  nameKo: string;
  nameEn: string;
  descKo: string;
  descEn: string;
  price: number;
  priceStatus: PriceStatus;
  tag: string;
  emoji: string;
  gradientBg: string;
  isFeatured: boolean;
  subwayInfo?: string;
  subwayInfoKo?: string;
  subwayInfoEn?: string;
  openingHours?: string;
  openingHoursKo?: string;
  openingHoursEn?: string;
  closedDays?: string;
  closedDaysKo?: string;
  closedDaysEn?: string;
  officialUrl?: string;
  imageUrl?: string;
  deepLink?: string;
  categoryType?: AttractionCategoryType;
}

export interface BilingualSpotDetail {
  categoryType?: AttractionCategoryType;
  nameKo: string;
  nameEn: string;
  descKo: string;
  descEn: string;
  subwayKo?: string;
  subwayEn?: string;
  hoursKo?: string;
  hoursEn?: string;
  closedKo?: string;
  closedEn?: string;
  imageUrl?: string;
}

/**
 * 정규화된 관광지 ID를 반환합니다. (seoul_rep_, kto_, kto_custom_ 접두사를 통일)
 */
export function normalizeSpotKey(id?: string): string {
  if (!id) return "";
  return id
    .replace(/^seoul_rep_/, "")
    .replace(/^kto_custom_/, "")
    .replace(/^kto_/, "")
    .trim();
}

/**
 * 서로 다른 접두사를 가진 장소 ID가 동일한 관광지를 가리키는지 판별합니다.
 */
export function isSameSpot(idA?: string, idB?: string): boolean {
  if (!idA || !idB) return false;
  if (idA === idB) return true;
  return normalizeSpotKey(idA) === normalizeSpotKey(idB);
}

